select * from customer limit 20

--1.What is the total revrnue generated by male vs. female customers?
select gender,sum (purchase_amount) as revenue
from customer
group by gender

--2.Which customer used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE LOWER(discount_applied) = 'yes'
AND purchase_amount >= (
    SELECT AVG(purchase_amount)
    FROM customer
);

--3. which are the top 5 productwith the height average review rating
select item_purchased,AVG(review_rating) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;